const raw = ($input.first().json.text || '').toLowerCase().trim();
let category = 'not_hr';
if (raw.includes('leave')) category = 'leave';
else if (raw.includes('salary')) category = 'salary';
else if (raw.includes('flex')) category = 'flexwork';

return [{
  json: {
    category,
    is_hr_request: category !== 'not_hr',
    raw_classification: raw
  }
}];

